import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

const words = ["Productivity", "Performance", "Portfolio", "Personal Growth"];

function Hero() {
    const [index, setIndex] = useState(0);
    const [subIndex, setSubIndex] = useState(0);
    const [reverse, setReverse] = useState(false);

    // Typewriter effect logic
    useEffect(() => {
        if (subIndex === words[index].length + 1 && !reverse) {
            setTimeout(() => setReverse(true), 2000);
            return;
        }

        if (subIndex === 0 && reverse) {
            setReverse(false);
            setIndex((prev) => (prev + 1) % words.length);
            return;
        }

        const timeout = setTimeout(() => {
            setSubIndex((prev) => prev + (reverse ? -1 : 1));
        }, reverse ? 75 : 150);

        return () => clearTimeout(timeout);
    }, [subIndex, index, reverse]);

    return (
        <section className="hero-section">
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.8 }}
                className="hero-content"
            >
                <span className="hero-subtitle">Redefining your workflow</span>
                <h1 className="hero-title">
                    Master Your <br />
                    <span className="typing-text">
                        {words[index].substring(0, subIndex)}
                        <span className="cursor">|</span>
                    </span>
                </h1>
                <p className="hero-description">
                    A unique, high-performance task management system designed to elevate
                    your daily output with professional-grade tools and aesthetics.
                </p>
            </motion.div>
        </section>
    );
}

export default Hero;
